// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether (constructor requires it)
        vm.deal(address(c), 1 ether);
        // Fund the caller
        address caller = address(0x1234);
        vm.deal(caller, 1 ether);
        // Call lockInGuess
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 1 ether}(abi.encodeWithSelector(c.lockInGuess.selector, bytes32(uint256(1))));
        // Assert the call succeeded (reference) — buggy would revert causing success == false
        assertTrue(success);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(this), 2 ether);
        bytes32 hash = keccak256("test");
        bool ok;
        try c.lockInGuess{value: 1 ether}(hash) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}
